--
-- Table structure for table `task_briefs`
--

CREATE TABLE `task_briefs` (
  `id` smallint(5) UNSIGNED NOT NULL COMMENT 'Unique identifier',
  `show_id` tinyint(2) UNSIGNED DEFAULT NULL COMMENT 'Show ID',
  `season_id` smallint(3) UNSIGNED DEFAULT NULL COMMENT 'Season ID',
  `episode_id` smallint(4) UNSIGNED DEFAULT NULL COMMENT 'Episode ID',
  `task_id` smallint(5) UNSIGNED DEFAULT NULL COMMENT 'Task ID',
  `sort_order` tinyint(2) UNSIGNED DEFAULT NULL COMMENT 'Sort Order',
  `brief_note` varchar(128) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Text to be shown before the brief text.',
  `brief_text` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Task brief text'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

